-- ============================================================
-- 0047 — Curadoria dos textos-base da RNC: Telecom (TC)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- TC-01 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a rota executada divergir do projeto a ponto de inviabilizar o lançamento das cordoalhas-guia ou comprometer a taxa de ocupação máxima admissível dos dutos.',
  texto_fundamentacao_normativa = 'A infraestrutura de dutos e caixas de passagem deve reproduzir fielmente as rotas, os diâmetros e os pontos de derivação definidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, garantindo a ocupação dentro dos limites de projeto e a presença das cordoalhas-guia em todos os trechos. Aplica-se a NBR 14565 (cabeamento estruturado de telecomunicações), que estabelece requisitos de dimensionamento, taxa de ocupação e infraestrutura de encaminhamento. O critério "Rotas, ocupação e cordoalhas-guia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, pois assegura a capacidade de lançamento e a manutenibilidade futura dos cabos.',
  texto_risco_consequencia = 'Dutos e caixas executados fora das rotas de projeto, com sobreocupação ou sem cordoalhas-guia, inviabilizam ou dificultam o lançamento dos cabos, forçam curvas fora do raio mínimo e podem exigir quebra de infraestrutura já concretada para correção, com retrabalho, sobrecusto e atraso do cronograma; sem cordoalha-guia, cada nova passagem de cabo depende de sondagem manual, elevando o risco de dano ao cabeamento. A permanência da condição mantém ativo o desvio até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar as rotas, os diâmetros e a ocupação executados com o projeto executivo aprovado, mapeando os trechos divergentes; (ii) adequar a infraestrutura — redimensionar dutos sobreocupados, refazer trechos fora de rota e instalar cordoalhas-guia em todos os segmentos previstos; (iii) evidenciar a correção com registro fotográfico e ensaio de passagem/mandril ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de climatização, de vedação ou de DPS expuser os ativos de telecom a risco iminente de dano ou de interrupção de serviço.',
  texto_fundamentacao_normativa = 'A sala técnica deve oferecer condições ambientais e de proteção compatíveis com a operação contínua dos equipamentos, o que abrange climatização dimensionada para a carga térmica, piso adequado (nivelado, antiestático ou elevado conforme previsto), vedação contra poeira e umidade e dispositivos de proteção contra surtos (DPS) instalados na alimentação. Aplicam-se a NBR 14565 (requisitos de sala de telecomunicações) e a NBR 5410 (instalações elétricas de baixa tensão), esta última quanto à instalação e coordenação do DPS, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Climatização, piso, vedação e DPS instalados" integra o plano de inspeção e constitui requisito verificável de aceitação do ambiente técnico.',
  texto_risco_consequencia = 'Sala técnica sem climatização adequada favorece sobreaquecimento e redução da vida útil dos ativos; falhas de vedação permitem ingresso de poeira e umidade, com corrosão e falhas intermitentes; piso inadequado gera acúmulo eletrostático e insegurança de manutenção; e a ausência de DPS deixa os equipamentos expostos a surtos de tensão e descargas, com risco de queima e indisponibilidade do serviço de telecomunicações. A permanência da condição mantém os ativos sob risco até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a carga térmica e restabelecer a climatização dimensionada, além de inspecionar o piso e as vedações do ambiente; (ii) sanar as deficiências — instalar/adequar climatização, corrigir piso e vedações e instalar o DPS na entrada de alimentação com a coordenação prevista; (iii) evidenciar a correção com registro fotográfico e medições ambientais/elétricas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — condição de segurança e de continuidade: rack sem equipotencialização ou com fixação insuficiente deve bloquear a energização até a regularização.',
  texto_fundamentacao_normativa = 'Os racks devem estar mecanicamente fixados à estrutura com o torque especificado pelo fabricante e integrados ao sistema de aterramento por meio de equipotencialização, condição que protege pessoas e equipamentos e garante referência de terra estável. Aplicam-se a NBR 5410 (instalações elétricas de baixa tensão) quanto à equipotencialização das massas e a NBR 5419 (proteção contra descargas atmosféricas) quanto à ligação equipotencial das partes metálicas, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e das especificações do fabricante para o torque de fixação. O critério "Torque de fixação e equipotencialização" integra o plano de inspeção e constitui requisito verificável de aceitação, aferível por chave de torque e por medição de continuidade/resistência de aterramento.',
  texto_risco_consequencia = 'Rack sem equipotencialização eficaz eleva o risco de choque elétrico ao operador e de diferença de potencial entre massas, podendo danificar equipamentos sensíveis em caso de falta ou surto; fixação sem o torque especificado compromete a estabilidade mecânica do conjunto, com risco de tombamento sob carga e afrouxamento progressivo por vibração. A permanência da condição mantém ativo o risco à segurança e à integridade dos ativos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reapertar a fixação dos racks com chave de torque, conforme especificação do fabricante, e verificar a continuidade do condutor de equipotencialização até a barra de aterramento; (ii) corrigir as não conformidades — refazer a ligação equipotencial e medir a resistência/continuidade de aterramento, ajustando o que estiver fora de faixa; (iii) evidenciar a correção com registro fotográfico e laudo de medição de aterramento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falta de redundância, de circuito dedicado ou de banco de baterias previsto puser em risco a continuidade de serviços essenciais.',
  texto_fundamentacao_normativa = 'A alimentação dos ativos de telecom deve ser provida por circuitos dedicados, devidamente identificados e, quando previsto o esquema redundante, por fontes AC/DC independentes, complementadas por banco de baterias onde o projeto o exigir. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão) quanto à setorização, dedicação e identificação dos circuitos e à proteção associada, observando-se ainda os requisitos de segurança da NR-10 em intervenções no sistema elétrico e no banco de baterias, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Circuitos dedicados e identificados; baterias quando previsto" integra o plano de inspeção e constitui requisito verificável de aceitação da instalação de energia.',
  texto_risco_consequencia = 'Alimentação sem redundância ou sem circuito dedicado torna o sistema de telecom vulnerável a uma única falha ou a interferências de outras cargas do quadro, com indisponibilidade do serviço; circuitos não identificados dificultam manobras e manutenção seguras, elevando o risco de desligamento indevido; a ausência do banco de baterias previsto elimina a autonomia durante faltas de energia, interrompendo os serviços essenciais. A permanência da condição mantém a instalação exposta à interrupção até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir os circuitos AC/DC quanto à dedicação, à redundância e à identificação, confrontando-os com o projeto e o diagrama unifilar aprovados; (ii) corrigir as pendências — segregar circuitos, restabelecer a redundância, identificar disjuntores e cabos e instalar/comissionar o banco de baterias previsto; (iii) evidenciar a correção com registro fotográfico e teste de comutação/autonomia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de identificação impedir a rastreabilidade da infraestrutura e a execução segura de manobras e manutenções.',
  texto_fundamentacao_normativa = 'Dutos, caixas de passagem e racks devem ser etiquetados de forma padronizada, legível e durável, permitindo a identificação inequívoca de rotas, pontos e ativos ao longo da vida útil da instalação. Aplica-se a NBR 14565 (cabeamento estruturado de telecomunicações), que estabelece requisitos de administração e identificação da infraestrutura de telecomunicações, complementada pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e pelo padrão de etiquetagem da obra. O critério "Dutos, caixas e racks etiquetados" integra o plano de inspeção e constitui requisito verificável de aceitação, essencial à rastreabilidade e à gestão do as-built.',
  texto_risco_consequencia = 'Infraestrutura sem identificação padronizada compromete a rastreabilidade de rotas e ativos, dificulta manobras e manutenções, aumenta o tempo de diagnóstico de falhas e o risco de intervenções em elemento errado, além de fragilizar o registro as-built exigido para o recebimento da obra. A permanência da condição mantém a instalação sem rastreabilidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os dutos, caixas e racks sem etiquetagem ou com identificação ilegível, confrontando com o padrão de etiquetagem e o projeto aprovados; (ii) aplicar a identificação padronizada, com etiquetas duráveis e legíveis, e atualizar a documentação as-built correspondente; (iii) evidenciar a correção com registro fotográfico das etiquetas instaladas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-01' and item_numero = 5;

-- TC-02 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver evidência de tração acima do limite ou curvatura abaixo do raio mínimo com risco de microfissura ou ruptura do cabo já lançado.',
  texto_fundamentacao_normativa = 'O lançamento do cabo óptico/OPGW deve respeitar a tração máxima de puxamento e os raios de curvatura (dinâmico durante o lançamento e estático após acomodação) definidos pela especificação técnica do fabricante do cabo e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixam os esforços admissíveis para preservar a integridade das fibras e da armação. O critério "Tensão máxima e raios de curvatura respeitados" constitui requisito verificável de aceitação da etapa, comprovável por registro do dinamômetro/célula de carga da máquina de tracionamento e por conferência dos raios nas roldanas, curvas e pontos de fixação. Na ausência de norma específica aplicável ao caso, a fundamentação apoia-se na especificação do fabricante, no projeto e nas boas práticas de instalação de cabos ópticos.',
  texto_risco_consequencia = 'O lançamento fora dos limites de tração ou com raios de curvatura inferiores ao mínimo pode induzir microcurvaturas, microfissuras e alongamento das fibras, elevando a atenuação e antecipando a falha do enlace, muitas vezes de forma latente e só detectável em operação. A permanência da condição mantém o cabo sob esforço residual e degradação progressiva até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper o lançamento e reconferir os parâmetros de tração e os raios de curvatura em roldanas, curvas e fixações, confrontando-os com a especificação do fabricante e o projeto executivo aprovado; (ii) reacomodar ou relançar o trecho afetado com controle do dinamômetro e roldanas de diâmetro adequado, e submeter o lance a OTDR para confirmar a ausência de degradação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e traço OTDR do trecho, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a atenuação da emenda comprometer o link budget do enlace ou reprovar o trecho na medição fim-a-fim.',
  texto_fundamentacao_normativa = 'Cada fusão deve apresentar atenuação dentro do valor máximo por emenda estabelecido no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e na especificação de instalação, com o valor medido registrado individualmente por emenda. O critério "Valores por emenda registrados" integra o plano de inspeção da obra e assegura a rastreabilidade da qualidade de cada fusão, condição verificável pela estimativa da máquina de fusão e pela confirmação por OTDR. Na ausência de norma específica aplicável a este item, a fundamentação apoia-se no critério de aceitação de projeto e nas boas práticas de emenda por fusão.',
  texto_risco_consequencia = 'Fusões com atenuação acima do critério ou sem registro por emenda comprometem o balanço de potência do enlace e impedem localizar e responsabilizar a emenda deficiente, acumulando perdas que só se manifestam na medição fim-a-fim ou em falhas de operação. A permanência da condição mantém emendas de qualidade não comprovada no enlace até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar os registros de atenuação por emenda e identificar as fusões fora do critério de projeto; (ii) refazer as fusões reprovadas (limpeza, clivagem e novo alinhamento), reensaiar e registrar o novo valor por emenda; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a tabela de atenuação por emenda revisada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falta de vedação ou de fixação expuser as emendas a umidade, tração ou queda da caixa, com risco de dano às fibras.',
  texto_fundamentacao_normativa = 'As caixas de emenda óptica devem estar estanques (vedação e selagem íntegras) e firmemente fixadas ao suporte, com a reserva técnica (loops) acondicionada conforme os comprimentos e raios definidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e na especificação do fabricante da caixa. O critério "Reserva técnica (loops) conforme projeto" constitui requisito verificável de aceitação, pois garante margem para futuras intervenções sem esforço sobre as emendas. Na ausência de norma específica aplicável a este item, a fundamentação apoia-se na especificação do fabricante, no projeto e nas boas práticas de acondicionamento de emendas.',
  texto_risco_consequencia = 'Caixas mal vedadas permitem ingresso de umidade e contaminação sobre as emendas, elevando a atenuação e provocando corrosão e falhas; a fixação deficiente e a reserva técnica insuficiente transferem esforços mecânicos às fibras e inviabilizam intervenções futuras, aumentando o risco de ruptura. A permanência da condição mantém as emendas desprotegidas e sob risco progressivo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reabrir e inspecionar a caixa, verificando a integridade dos elementos de vedação/selagem e a firmeza da fixação; (ii) restabelecer a vedação (substituindo vedantes quando necessário), refixar a caixa e reorganizar a reserva técnica (loops) com os comprimentos e raios de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da caixa fechada, fixada e da reserva acondicionada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de OTDR bidirecional documentado impedir a aceitação do trecho ou ocultar emendas/eventos fora do critério.',
  texto_fundamentacao_normativa = 'O ensaio OTDR deve ser executado nos dois sentidos (bidirecional) e documentado por fibra, com os traços e a tabela de eventos assinados pelo responsável técnico, conforme o plano de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A medição bidirecional é necessária porque compensa as diferenças de retroespalhamento entre fibras e evita o mascaramento de eventos (ganhos aparentes), permitindo caracterizar corretamente cada emenda e conector. O critério "Relatórios por fibra com assinatura" assegura rastreabilidade e é requisito verificável de aceitação; na ausência de norma específica aplicável, a fundamentação apoia-se no procedimento de comissionamento e nas boas práticas de ensaio óptico.',
  texto_risco_consequencia = 'A falta de OTDR bidirecional documentado e assinado por fibra impede validar o enlace e localizar eventos com precisão, deixando emendas e conectores fora de critério sem detecção e sem rastreabilidade da responsabilidade técnica pelo ensaio. A permanência da condição mantém o trecho sem caracterização confiável do enlace até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) programar e executar o OTDR nos dois sentidos para as fibras pendentes ou com documentação incompleta; (ii) consolidar os relatórios por fibra, com traços, tabela de eventos e assinatura do responsável técnico, tratando eventuais eventos fora de critério identificados; (iii) evidenciar a correção anexando os relatórios OTDR bidirecionais assinados e registro fotográfico ({{evidencia_foto_correcao}}) do ensaio, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a potência fim-a-fim medida ultrapassar o link budget de projeto, reprovando a aceitação do enlace.',
  texto_fundamentacao_normativa = 'A medição de potência óptica fim-a-fim (perda de inserção com fonte de luz e power meter) deve resultar em atenuação total dentro do link budget definido no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, considerando o coeficiente de atenuação da fibra, o número de emendas e conectores e a margem de projeto. O critério "Link budget dentro do projeto" constitui requisito verificável de aceitação do enlace, pois traduz o desempenho real disponível para o equipamento ativo. Na ausência de norma específica aplicável a este item, a fundamentação apoia-se no projeto, na especificação da fibra e nas boas práticas de comissionamento óptico.',
  texto_risco_consequencia = 'Enlace com potência fim-a-fim fora do link budget não oferece margem suficiente para os equipamentos ativos, resultando em baixa relação sinal-ruído, erros de bit, indisponibilidade e necessidade de retrabalho após a energização. A permanência da condição mantém o enlace sem margem óptica adequada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir a medição de perda de inserção fim-a-fim com padrões de referência calibrados e confrontar o resultado com o link budget de projeto; (ii) diagnosticar por OTDR a origem do excesso de perda (emenda, conector ou trecho) e corrigir o elemento responsável, reensaiando o enlace; (iii) evidenciar a correção anexando o relatório de potência fim-a-fim dentro do link budget e registro fotográfico ({{evidencia_foto_correcao}}) da medição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor quando a ausência de identificação padronizada gerar risco real de conexão incorreta ou dificultar a operação e manutenção do enlace.',
  texto_fundamentacao_normativa = 'As fibras, cordões e portas devem ser identificados segundo o padrão de cores e a rotulagem definidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e no procedimento de identificação da obra, de forma legível e durável. O critério "Padrão de cores/rotulagem aplicado" integra o as-built e o plano de inspeção, pois assegura a correta associação entre fibra, porta e circuito, condição verificável por conferência visual contra o projeto. Na ausência de norma específica aplicável a este item, a fundamentação apoia-se no projeto, no padrão de identificação adotado e nas boas práticas de documentação de rede óptica.',
  texto_risco_consequencia = 'A identificação ausente, divergente do padrão ou ilegível favorece conexões cruzadas, dificulta a localização de fibras em manutenção e compromete a confiabilidade do as-built, elevando o tempo de reparo e o risco de interrupção acidental de circuitos ativos. A permanência da condição mantém a rede sem rastreabilidade confiável das fibras até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a identificação de fibras, cordões e portas contra o padrão de cores e a rotulagem de projeto, listando as divergências; (ii) reetiquetar os elementos não conformes com material durável e legível e atualizar o as-built correspondente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das etiquetas aplicadas e a documentação as-built revisada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-02' and item_numero = 6;

-- TC-03 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver energização de equipamento fora do layout aprovado do rack, risco de choque/arco elétrico ao pessoal ou energização de circuito não liberado.',
  texto_fundamentacao_normativa = 'Os switches, roteadores e rádios devem estar instalados nas posições e ocupar as unidades de rack definidas no layout aprovado, com energização executada por profissional habilitado e circuitos devidamente liberados. A verificação apoia-se no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa a disposição física dos ativos no rack, e nas boas práticas de segurança elétrica aplicáveis à energização de equipamentos, que exigem liberação formal de circuito, aterramento adequado e execução por profissional habilitado. O critério "Switches/roteadores/rádios conforme layout do rack" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Equipamentos instalados fora do layout aprovado ou energizados sem liberação comprometem a rastreabilidade física dos ativos, dificultam manutenção e podem gerar sobreaquecimento por má distribuição de dissipação no rack, além de expor o pessoal a risco elétrico durante intervenções. A permanência da condição mantém o ativo em operação sem conformidade com o projeto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a posição e a fixação de cada equipamento contra o layout aprovado do rack, reposicionando os ativos divergentes; (ii) validar a energização com profissional habilitado, confirmando liberação de circuito, aterramento e ausência de sobrecarga; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do rack organizado e energizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a categoria instalada for inferior à de projeto ou quando faltarem relatórios de certificação que comprovem o desempenho dos enlaces.',
  texto_fundamentacao_normativa = 'O cabeamento deve atender à categoria de desempenho especificada em projeto e ser comprovado por certificação de campo com equipamento calibrado, gerando relatório aprovado (PASS) por enlace. Aplicam-se a ABNT NBR 14565 (cabeamento estruturado de telecomunicações), que estabelece os parâmetros de desempenho e os ensaios de certificação, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define a categoria requerida. O critério "Categoria conforme projeto; relatórios de certificação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Cabeamento não certificado ou de categoria inferior à de projeto pode apresentar perda de inserção, diafonia e retorno acima dos limites, degradando a taxa de transmissão, elevando a taxa de erros e comprometendo a confiabilidade dos serviços que dependem do enlace. A ausência de relatório impede a aceitação técnica e mantém o desvio latente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar a categoria dos cabos, conectores e patch cords instalados frente à especificação de projeto; (ii) certificar os enlaces com equipamento calibrado, corrigindo terminações e substituindo lances reprovados até obter resultado PASS; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar os relatórios de certificação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se a ausência ou o erro de identificação comprometer a manutenção, o comissionamento ou a segurança de intervenções em ativos críticos.',
  texto_fundamentacao_normativa = 'Portas, patch panels e cordões devem ser identificados de forma unívoca e permanente, com a documentação como construído refletindo fielmente as conexões físicas. Aplicam-se a ABNT NBR 14565 (cabeamento estruturado de telecomunicações), na parte relativa à administração e identificação da infraestrutura, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, com os planos de nomenclatura. O critério "Como construído documentado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A falta ou a inconsistência de identificação e do como construído dificulta a localização de enlaces, aumenta o tempo de diagnóstico e reparo, eleva o risco de desconexão indevida de circuitos em operação e propaga erros de documentação para a fase de operação e manutenção. A condição permanece prejudicando a rastreabilidade da rede até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar e aplicar a identificação de todas as portas, patch panels e cordões conforme o plano de nomenclatura aprovado, com etiquetas legíveis e duráveis; (ii) atualizar a documentação como construído, conferindo cada ponta contra a conexão física real; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das etiquetas aplicadas e entregar o as-built revisado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o sincronismo temporal for requisito de proteção, teleproteção ou registro de eventos e a redundância prevista não estiver operante.',
  texto_fundamentacao_normativa = 'A fonte de sincronismo GPS deve estar operante e, quando previsto em projeto, com redundância de fontes de tempo, disciplinando os relógios dos equipamentos que dependem de base temporal comum. Na ausência de norma específica aplicável de forma inequívoca a este item e disciplina, a fundamentação apoia-se no critério de aceitação, nas boas práticas de sincronização de sistemas de telecomunicações e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e respectiva especificação técnica, que definem as fontes de tempo e a redundância exigida. O critério "Fontes de tempo redundantes quando previsto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A perda ou indisponibilidade do sincronismo GPS, ou a ausência da redundância prevista, provoca deriva entre os relógios dos equipamentos, comprometendo a correlação de eventos, os registros com carimbo de tempo e funções que dependem de base temporal precisa, com impacto na análise de ocorrências e na coordenação de sistemas. A condição mantém a rede sem referência temporal confiável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a instalação da antena e a recepção do sinal GPS, confirmando o número de satélites, a qualidade do sinal e o travamento da fonte de tempo; (ii) validar a redundância prevista em projeto, testando a comutação entre fontes de tempo e ajustando parâmetros de distribuição do sincronismo aos equipamentos clientes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e telas de status de sincronismo operante, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a ausência de segregação entre a rede operacional e a corporativa expõe ativos críticos, devendo ser tratada com prioridade e bloqueio da liberação até a correção.',
  texto_fundamentacao_normativa = 'A rede deve implementar a segregação lógica definida em projeto, com VLANs e zonas separando o domínio operacional do corporativo e restringindo o tráfego entre eles conforme as regras aprovadas. Na ausência de norma específica que se aplique de forma inequívoca a este item e disciplina, a fundamentação apoia-se no critério de aceitação, nas boas práticas de segmentação e segurança de redes (zonas e controle de tráfego entre domínios) e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define a arquitetura lógica e as VLANs. O critério "VLANs/zonas (operacional × corporativa) implementadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência ou a implementação incorreta da segregação lógica permite trânsito indevido entre a rede corporativa e a operacional, ampliando a superfície de ataque, favorecendo a propagação de incidentes cibernéticos até ativos críticos e comprometendo a disponibilidade e a integridade dos sistemas de operação. A condição mantém a rede exposta enquanto não for efetivamente corrigida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a configuração de VLANs e zonas nos equipamentos frente à arquitetura lógica de projeto, identificando domínios indevidamente interligados; (ii) reimplementar a segregação e as regras de controle de tráfego entre operacional e corporativa, testando o isolamento e as exceções autorizadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das configurações e testes de isolamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando não houver qualquer backup válido das configurações dos ativos, ampliando o tempo de recuperação em caso de falha.',
  texto_fundamentacao_normativa = 'As configurações dos ativos de rede devem ser copiadas, versionadas e entregues, assegurando a recuperação dos equipamentos e a rastreabilidade das alterações. Na ausência de norma específica aplicável de forma inequívoca a este item e disciplina, a fundamentação apoia-se no critério de aceitação, nas boas práticas de gestão de configuração e continuidade operacional e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e respectivos requisitos de entrega documental. O critério "Arquivos versionados e entregues" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência de backup versionado das configurações eleva substancialmente o tempo de restabelecimento após falha ou substituição de equipamento, obriga à reconfiguração manual sujeita a erros e impede a rastreabilidade das alterações aplicadas, com risco à continuidade dos serviços. A condição mantém a rede sem rede de proteção documental até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) extrair a configuração corrente de cada ativo (switches, roteadores e rádios), conferindo a consistência dos arquivos; (ii) versionar os backups em repositório controlado, com identificação de data e revisão, e formalizar a entrega conforme os requisitos documentais do projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) ou captura do repositório com os arquivos versionados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-03' and item_numero = 6;

-- TC-04 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se pontos de comando ou de intertravamento estiverem trocados, invertidos ou não refletidos no supervisório, por afetar a operação e a segurança do sistema',
  texto_fundamentacao_normativa = 'A lista de pontos (comandos, estados e medições) deve ser conferida ponto a ponto contra a base do supervisório, assegurando que cada sinal de campo corresponda exatamente ao endereço, à descrição e à polaridade previstos na engenharia de automação e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Comandos, estados e medições × supervisório" integra o plano de comissionamento e constitui requisito verificável de aceitação, pois é a correspondência biunívoca entre campo e IHM que garante a fidedignidade da supervisão e do controle. A verificação segue boas práticas de comissionamento de sistemas de telecontrole, com registro individualizado de cada ponto testado.',
  texto_risco_consequencia = 'Pontos não conferidos ou divergentes entre campo e supervisório podem gerar indicações falsas de estado, medições incorretas e, sobretudo, comandos enviados a equipamento diverso do pretendido, expondo a operação a manobras indevidas, indisponibilidade e risco à integridade de pessoas e ativos. A permanência da condição mantém o supervisório com base não confiável até a efetiva correção e reteste. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar a conferência ponto a ponto de comandos, estados e medições, confrontando endereçamento, descrição e polaridade de cada sinal com a lista de pontos e o supervisório; (ii) corrigir na base do supervisório e/ou no campo as divergências identificadas, revalidando os pontos afetados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de pontos assinada com o resultado de cada teste, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o protocolo em teste for o de intertravamento/proteção (IEC 61850 GOOSE) ou se a falha impedir a supervisão de bay essencial',
  texto_fundamentacao_normativa = 'Os protocolos de comunicação devem ser testados conforme a arquitetura definida no projeto, tipicamente IEC 60870-5-104 (telecontrole com centro de operação) e/ou IEC 61850 (comunicação em subestação), garantindo que mapeamento, tipos de dado, qualidade e tempos estejam de acordo com o especificado no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "104/61850 conforme arquitetura do projeto" é requisito verificável de aceitação porque a interoperabilidade correta entre IEDs, gateway e supervisório depende da aderência ao perfil de protocolo projetado. Os testes seguem as próprias normas técnicas dos protocolos (IEC 60870-5-104 e IEC 61850) e o plano de comissionamento da obra.',
  texto_risco_consequencia = 'Protocolos não testados ou configurados fora da arquitetura de projeto podem resultar em perda de comunicação, dados com qualidade inválida, dessincronização de tempo e falha de comandos entre IEDs e supervisório, comprometendo a supervisão e o controle remoto da instalação. A permanência da condição mantém a camada de comunicação sem garantia de interoperabilidade até a efetiva correção e reteste. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a configuração de comunicação (IEC 60870-5-104 e/ou IEC 61850) com a arquitetura e o mapa de comunicação do projeto, identificando não conformidades de perfil, endereçamento e parametrização; (ii) reparametrizar gateway/IEDs e reexecutar os testes de protocolo, incluindo qualidade de dado, sincronismo de tempo e resposta a comandos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatórios/capturas de comunicação comprovando o pleno funcionamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a redundância é barreira de disponibilidade; manter Crítica sempre que o failover não comutar automaticamente ou não restabelecer a supervisão dentro do tempo de projeto',
  texto_fundamentacao_normativa = 'A redundância de canais de comunicação (principal/backup) deve ser efetivamente testada com simulação de falha, comprovando a comutação automática (failover) sem perda inaceitável de supervisão e controle, conforme a arquitetura de disponibilidade do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Canais principal/backup comutando corretamente" é requisito verificável de aceitação porque uma redundância não comprovada equivale, na prática, a inexistência de redundância. A verificação segue boas práticas de comissionamento de sistemas de telecontrole, exigindo teste destrutivo controlado do canal principal e evidência do retorno automático.',
  texto_risco_consequencia = 'Redundância não testada ou com failover inoperante implica que, na falha real do canal principal, a instalação pode perder supervisão e telecomando junto ao centro de operação exatamente no momento crítico, elevando o tempo de indisponibilidade e dificultando a atuação em contingência. A permanência da condição mantém a suposta redundância sem comprovação até a efetiva correção e reteste. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar o teste de failover simulando a queda do canal principal e verificando a comutação automática para o backup, medindo o tempo de restabelecimento da comunicação; (ii) corrigir a configuração de roteamento/redundância e, se necessário, o meio físico, até que a comutação ocorra dentro do requisito de projeto e retorne ao canal principal quando restabelecido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de teste de failover com tempos de comutação registrados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a latência exceder o limite ONS/COS a ponto de inviabilizar telecomando ou funções de tempo crítico da operação',
  texto_fundamentacao_normativa = 'A latência de comunicação fim a fim deve ser medida e registrada, comprovando o atendimento aos requisitos de tempo estabelecidos pelo ONS/COS e pela especificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Medições registradas (requisitos ONS/COS)" é requisito verificável de aceitação porque o desempenho temporal do telecontrole condiciona a atualização de estados e medições e a execução tempestiva de comandos junto ao centro de operação. A verificação apoia-se nos requisitos de desempenho definidos pelo operador do sistema (ONS/COS) e em boas práticas de comissionamento, com registro objetivo das medições realizadas.',
  texto_risco_consequencia = 'Latência acima do requisito degrada a atualização de dados no centro de operação e retarda a resposta a comandos, prejudicando a supervisão em tempo real, a coordenação de manobras e o cumprimento das obrigações de desempenho perante o ONS/COS. A permanência da condição mantém o sistema com desempenho temporal não comprovado ou insuficiente até a efetiva correção e reteste. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir as medições de latência fim a fim em condições representativas de operação, comparando os valores com o requisito ONS/COS aplicável; (ii) tratar as causas de latência excessiva (dimensionamento de enlace, parametrização de gateway/IEDs, qualidade do meio de transmissão) e revalidar o desempenho; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório com as medições de latência registradas e aprovadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a energização/operação do empreendimento estiver condicionada ao comissionamento ponto a ponto formalizado com COS/ONS e este não estiver concluído e aceito',
  texto_fundamentacao_normativa = 'O comissionamento com o centro de operação deve ser executado ponto a ponto e formalizado com o COS/ONS, comprovando em conjunto com o operador que cada sinal e comando é corretamente recebido, indicado e atuado no ambiente do centro de operação, em conformidade com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Ponto a ponto com COS/ONS formalizado" é requisito verificável de aceitação porque a integração operacional só se considera concluída com o aceite documentado do centro de operação. A atividade segue os procedimentos de integração do operador do sistema (COS/ONS) e o plano de comissionamento da obra.',
  texto_risco_consequencia = 'Comissionamento não realizado ponto a ponto ou não formalizado com o COS/ONS deixa a integração operacional sem validação conjunta, podendo levar o centro de operação a supervisionar e comandar a instalação com base não confirmada, além de expor o empreendimento a restrições de entrada em operação. A permanência da condição mantém a integração operacional sem aceite formal até a efetiva correção e conclusão. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reprogramar e executar com o COS/ONS o comissionamento ponto a ponto, verificando conjuntamente a recepção de estados/medições e a atuação de cada comando no ambiente do centro de operação; (ii) tratar as pendências identificadas na integração e revalidar os pontos afetados junto ao operador; (iii) evidenciar a conclusão com registro fotográfico ({{evidencia_foto_correcao}}) e a documentação de comissionamento formalizada e assinada pelo COS/ONS, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a permanência de senhas padrão é vulnerabilidade de segurança cibernética de acesso direto; manter Crítica enquanto houver credencial de fábrica ativa em qualquer ativo do sistema',
  texto_fundamentacao_normativa = 'As senhas padrão de fábrica de IEDs, gateways, switches e estações do sistema de telecontrole devem ser substituídas por credenciais próprias, com hardening básico aplicado e registrado (contas, perfis de acesso e serviços desnecessários desabilitados), conforme a política de segurança da instalação e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Hardening básico aplicado e registrado" é requisito verificável de aceitação porque credenciais padrão são amplamente conhecidas e constituem vetor direto de acesso não autorizado. A prática alinha-se às boas práticas de segurança cibernética de sistemas de automação e controle industrial (família IEC 62443) e aos requisitos de segurança do operador do sistema.',
  texto_risco_consequencia = 'A manutenção de senhas padrão e a ausência de hardening permitem acesso não autorizado à configuração e ao comando dos equipamentos de telecontrole, com risco de manipulação de parâmetros, envio de comandos indevidos e comprometimento da disponibilidade e da segurança operacional da instalação. A permanência da condição mantém ativa uma vulnerabilidade crítica de acesso até a efetiva correção e comprovação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar todos os ativos do sistema e substituir as senhas padrão por credenciais fortes e individualizadas, sob controle de acesso; (ii) aplicar o hardening básico (desabilitar contas/serviços desnecessários, definir perfis de acesso e registrar a configuração), preservando a rastreabilidade das alterações; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de hardening por ativo, sem expor as senhas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-04' and item_numero = 6;

-- TC-05 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o ponto cego recair sobre acesso, cofre, caixa ou área crítica definida no plano de segurança, deixando ativo de alto valor sem cobertura',
  texto_fundamentacao_normativa = 'O posicionamento, o campo de visão e a sobreposição das câmeras devem reproduzir o mapa de cobertura do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e a memória de cálculo de enquadramento (lente, altura e ângulo). O critério "Ângulos e pontos cegos verificados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação: a cobertura contratada só se considera atendida quando o levantamento em campo confirma a ausência de zonas mortas nos setores previstos. Na ausência de norma técnica específica de enquadramento aplicável a este item, a aceitação fundamenta-se no critério do checklist, na especificação técnica do sistema e nas boas práticas de projeto de CFTV (varredura de campo com registro dos ângulos reais frente aos ângulos de projeto).',
  texto_risco_consequencia = 'Câmeras fora do enquadramento de projeto criam pontos cegos em setores que deveriam estar cobertos, permitindo que eventos de segurança ocorram sem registro útil, comprometendo a apuração de ocorrências e a própria finalidade do sistema. A permanência da condição mantém o setor descoberto e a vulnerabilidade ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar em campo o campo de visão real de cada câmera do trecho com o mapa de cobertura do projeto executivo aprovado, mapeando as zonas mortas; (ii) reposicionar, ajustar altura/ângulo ou complementar pontos de câmera até eliminar os pontos cegos nos setores previstos; (iii) evidenciar a correção com registro fotográfico das imagens ao vivo dos setores antes descobertos ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a retenção configurada for inferior ao mínimo exigido em contrato ou por exigência legal/regulatória aplicável ao empreendimento, ou quando não houver gravação alguma',
  texto_fundamentacao_normativa = 'O tempo de retenção, a taxa de quadros e a resolução de gravação devem atender ao requisito de projeto e à especificação técnica do sistema, dimensionamento que baliza a capacidade de armazenamento (NVR/servidor) do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Como as gravações contêm imagens de pessoas identificáveis, o tratamento e o prazo de guarda sujeitam-se à Lei nº 13.709/2018 (LGPD), que exige finalidade e período de retenção definidos. O critério "Dias de retenção conforme requisito" é requisito verificável de aceitação, confirmado por conferência das configurações do gravador e do cálculo de dias efetivos de armazenamento.',
  texto_risco_consequencia = 'Retenção configurada abaixo do requisito faz com que gravações sejam sobrescritas antes de o evento ser necessário, tornando o sistema incapaz de fornecer prova de ocorrências no prazo contratado e expondo o empreendimento a não conformidade contratual e a inadequação frente à LGPD quanto à guarda das imagens. A permanência da condição mantém a perda contínua de registros a cada ciclo de sobrescrita. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir nas configurações do gravador o período de retenção, a resolução e a taxa de quadros ativos, confrontando-os com o requisito de projeto e a capacidade de armazenamento dimensionada; (ii) ajustar a configuração e, se necessário, ampliar o armazenamento para assegurar os dias de retenção exigidos, validando por teste de gravação contínua; (iii) evidenciar a correção com registro fotográfico da tela de configuração e do cálculo de dias de retenção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se de barreira de detecção de intrusão; manter Crítica sempre que houver setor de perímetro sem detecção ativa, rebaixando a Maior apenas quando a falha for pontual, redundada por outro sensor e sem exposição de área sensível',
  texto_fundamentacao_normativa = 'Os sensores de perímetro, a cerca monitorada e as zonas de alarme devem estar operantes e corretamente setorizados conforme o projeto de detecção de intrusão constante do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e a especificação técnica do sistema. O critério "Sensores/cerca monitorada testados" é requisito verificável de aceitação: cada zona deve ser disparada em teste funcional e a sinalização correspondente confirmada na central. Na ausência de norma técnica específica aplicável a este item, a aceitação fundamenta-se no critério do checklist, na especificação do fabricante e nas boas práticas de comissionamento de sistemas de detecção perimetral (teste zona a zona com verificação de sinalização e de eventuais pontos de escalada/falha).',
  texto_risco_consequencia = 'Sensores de perímetro inoperantes ou zonas não disparando permitem intrusão sem detecção nem alarme, anulando a primeira barreira de segurança do empreendimento e expondo pessoas e patrimônio a acesso não autorizado sem aviso à central. A permanência da condição mantém o perímetro desprotegido de forma silenciosa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar teste funcional zona a zona de todos os sensores e da cerca monitorada, registrando quais não dispararam ou não sinalizaram na central; (ii) reparar, substituir ou reajustar sensores/segmentos e reconfigurar a setorização até que cada zona dispare e sinalize corretamente; (iii) evidenciar a correção com registro fotográfico do teste de disparo e da recepção do alarme na central ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando níveis de acesso indevidos liberarem áreas restritas/críticas ou quando não houver registro (log) de eventos de acesso, impedindo rastreabilidade',
  texto_fundamentacao_normativa = 'Os cadastros de usuários, os níveis de permissão por porta/área e o registro cronológico de eventos de acesso devem refletir a matriz de acessos e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, garantindo o princípio de menor privilégio. Como o sistema trata dados pessoais de titulares (identificação, credenciais e histórico de deslocamento), a guarda e o uso desses registros sujeitam-se à Lei nº 13.709/2018 (LGPD). O critério "Cadastros, níveis e registros de eventos" é requisito verificável de aceitação, confirmado por teste de liberação/bloqueio por nível e por conferência de que os eventos ficam efetivamente logados.',
  texto_risco_consequencia = 'Controle de acesso com níveis mal atribuídos libera áreas restritas a pessoas não autorizadas, e a ausência de log de eventos impede a rastreabilidade de quem acessou o quê e quando, comprometendo a segurança das áreas sensíveis e a apuração de incidentes, além de inadequação frente à LGPD quanto ao registro do tratamento. A permanência da condição mantém os acessos indevidos e a lacuna de rastreabilidade ativos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar a matriz de acessos, testando por credencial de amostra a liberação e o bloqueio de cada nível nas portas/áreas correspondentes; (ii) corrigir cadastros e níveis de permissão conforme o projeto e habilitar/validar o registro cronológico de eventos de acesso; (iii) evidenciar a correção com registro fotográfico do teste de acesso por nível e do log de eventos gerado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o alarme não chegar à central/monitoramento 24h contratada, pois a falha na notificação anula a resposta a incidentes de todo o sistema',
  texto_fundamentacao_normativa = 'A integração entre os subsistemas (CFTV, alarme, controle de acesso) e a central de monitoramento deve entregar as notificações ao destino definido no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e na especificação de integração, com confirmação de recebimento pelo operador. O critério "Notificações chegando ao destino definido" é requisito verificável de aceitação: cada evento de teste deve ser gerado no campo e confirmado na recepção da central/monitoramento. Na ausência de norma técnica específica aplicável a este item, a aceitação fundamenta-se no critério do checklist, na especificação de integração e nas boas práticas de comissionamento (teste ponta a ponta com confirmação do destinatário e do tempo de chegada).',
  texto_risco_consequencia = 'Falha na integração faz com que alarmes e eventos não cheguem à central de monitoramento, de modo que uma intrusão ou ocorrência real não gera resposta, anulando na prática a capacidade de reação de todo o sistema de segurança por mais que os sensores locais funcionem. A permanência da condição mantém o monitoramento cego a eventos reais até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar teste ponta a ponta gerando eventos de cada subsistema e verificando a chegada e o registro da notificação no destino definido; (ii) corrigir a configuração de integração, rotas, credenciais ou canal de comunicação até que todas as notificações cheguem e sejam confirmadas pela central; (iii) evidenciar a correção com registro fotográfico do evento gerado e da respectiva notificação recebida no destino ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-05' and item_numero = 5;

-- TC-06 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o cenário não percorrido envolver funções essenciais de missão (voz de emergência, telemetria de segurança ou enlaces críticos), ou quando a lacuna impedir a liberação da etapa para operação',
  texto_fundamentacao_normativa = 'O teste fim-a-fim integrado tem por objetivo comprovar que os subsistemas de telecom operam de forma articulada, reproduzindo as condições reais de uso, e não apenas isoladamente. O critério "Cenários do plano aprovado percorridos" torna a aceitação verificável: cada caso de teste previsto no plano de testes aprovado deve ser executado, registrado e ter resultado confrontado com o requisito. A demonstração integrada e a rastreabilidade dos casos de teste ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, integram o plano de inspeção da obra e constituem requisito de aceitação da etapa. Fundamenta-se pelo critério do item, pelas especificações do projeto e pelas boas práticas de comissionamento de sistemas de telecomunicações.',
  texto_risco_consequencia = 'Liberar o sistema sem percorrer integralmente os cenários do plano aprovado significa aceitar a integração sem evidência de que os subsistemas interoperam sob condições reais, permitindo que falhas de interface, temporização ou roteamento só se manifestem em operação, com indisponibilidade de serviço, retrabalho tardio e discussão de responsabilidade após o aceite. A permanência da condição mantém a etapa sem comprovação de conformidade funcional. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar, no plano de testes aprovado, os cenários não executados ou reprovados, registrando a rastreabilidade caso a caso; (ii) reexecutar os testes fim-a-fim pendentes na presença da fiscalização, tratando eventuais não conformidades de integração até a aprovação de cada cenário; (iii) consolidar os resultados em relatório de teste integrado, com evidência fotográfica e de tela ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica quando o failover proteger enlaces ou serviços essenciais/redundantes de projeto; rebaixar a Maior apenas se a redundância for acessória e houver caminho alternativo operacional comprovado',
  texto_fundamentacao_normativa = 'A demonstração de failover geral verifica que os mecanismos de redundância previstos (enlaces, equipamentos, rotas e alimentação) assumem a operação automaticamente diante de falha, restabelecendo o serviço dentro do tempo de recuperação especificado. O critério "Quedas simuladas com recuperação conforme requisito" exige que a resiliência seja comprovada por ensaio controlado — e não presumida da mera existência do equipamento redundante. Os tempos de convergência e a continuidade de serviço devem atender aos requisitos de disponibilidade do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Fundamenta-se pelo critério do item, pelas especificações de disponibilidade do projeto e pelas boas práticas de comissionamento de sistemas redundantes de telecom.',
  texto_risco_consequencia = 'Aceitar a redundância sem simular quedas e medir a recuperação equivale a supor proteção que não foi comprovada: em falha real, o failover pode não atuar, atuar fora do tempo requerido ou causar indisponibilidade em cascata, comprometendo serviços que o projeto classificou como essenciais e frustrando o próprio objetivo da arquitetura redundante. A permanência da condição mantém a alta disponibilidade não verificada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) definir com a fiscalização o roteiro de simulação de falhas (queda de enlace primário, de equipamento e de alimentação, conforme a arquitetura), com os tempos de recuperação requeridos; (ii) executar as simulações de queda, medindo o tempo de convergência e confirmando a continuidade do serviço em cada evento, corrigindo configurações de redundância que não atendam ao requisito; (iii) registrar os resultados com evidência fotográfica e de logs/tela ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a certificação ausente ou reprovada indicar enlace fora de especificação (atenuação, perda de retorno, mapa de fios ou orçamento óptico), condição que invalida a aceitação do trecho',
  texto_fundamentacao_normativa = 'Os relatórios e certificações são a evidência objetiva de que a infraestrutura de telecom foi executada dentro dos parâmetros especificados. Ensaios de OTDR e certificação de cabeamento aferem, entre outros, atenuação, perda de retorno, comprimento e o mapa de fios, enquanto os testes ponto a ponto e os registros de configuração comprovam a operação dos enlaces e a parametrização dos ativos. Para o cabeamento estruturado, aplicam-se a ABNT NBR 14565 (cabeamento estruturado) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixam os limites de aceitação e o escopo de ensaios. O critério "OTDR, cabeamento, ponto a ponto e configurações" integra o plano de inspeção e constitui requisito documental verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Entregar a etapa sem os relatórios e certificações — ou com resultados reprovados — impede confirmar que os enlaces atendem aos limites de projeto e retira a rastreabilidade necessária à operação e à manutenção, permitindo que trechos fora de especificação (excesso de atenuação, emenda deficiente, mapa de fios invertido) permaneçam ocultos até a falha em serviço, com difícil imputação de responsabilidade após o aceite. A permanência da condição mantém a infraestrutura sem comprovação metrológica de conformidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar quais ensaios e documentos estão ausentes, incompletos ou reprovados (OTDR, certificação de cabeamento, testes ponto a ponto e backup de configurações); (ii) reexecutar os ensaios pendentes com instrumento calibrado e corrigir os enlaces reprovados até que os resultados fiquem dentro dos limites da NBR 14565 e do projeto, refazendo a certificação; (iii) consolidar e entregar os relatórios e certificados assinados, com evidência fotográfica dos ensaios ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando as divergências entre o as built e o executado comprometerem a operação, a manutenção ou a rastreabilidade de enlaces e ativos críticos',
  texto_fundamentacao_normativa = 'O as built de telecom documenta a topologia efetivamente executada — traçados, pontos, ativos, identificação de portas e cabos — e as listas correspondentes, servindo de base para operação, expansão e manutenção do sistema. O critério "Topologia e listas conforme executado" exige fidelidade entre o desenhado e o instalado, incluindo as alterações ocorridas em obra frente ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Fundamenta-se pelo critério do item, pela exigência contratual de documentação final e pelas boas práticas de gestão da configuração de redes de telecom, que tornam o as built requisito verificável de encerramento da etapa.',
  texto_risco_consequencia = 'Um as built ausente, desatualizado ou divergente do executado transfere à operação um sistema sem representação fiel de sua topologia, dificultando localização de falhas, planejamento de intervenções e futuras expansões, e elevando o tempo de reparo por depender de investigação de campo a cada ocorrência. A permanência da condição mantém a documentação final incompatível com o instalado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar em campo a topologia, a identificação de pontos/portas e as listas de cabos e ativos com o que foi efetivamente instalado; (ii) atualizar os desenhos e listas de as built, incorporando todas as divergências e alterações de obra e mantendo a identificação coerente com a etiquetagem física; (iii) entregar o as built revisado e assinado, com evidência fotográfica que ateste a correspondência entre documento e instalação ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o aceite for pré-requisito contratual para entrada em operação, medição ou transferência de responsabilidade, e não puder ser assinado por pendências técnicas em aberto',
  texto_fundamentacao_normativa = 'O aceite formal, materializado no termo de aceitação do sistema de telecom, é o ato que consolida a transferência do sistema à contratante e o reconhecimento de que os testes, certificações e documentação foram concluídos e aprovados. O critério "Termo de aceitação do sistema de telecom" condiciona o encerramento à existência de documento assinado pelas partes, lastreado nas evidências de conformidade e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Fundamenta-se pelo critério do item, pela previsão contratual de aceitação da etapa e pelas boas práticas de encerramento de comissionamento, que exigem o aceite como requisito formal e verificável.',
  texto_risco_consequencia = 'A ausência do termo de aceitação assinado deixa indefinido o marco de transferência de responsabilidade e de início das garantias, expondo as partes a divergências sobre o estado de entrega do sistema e permitindo que o sistema entre em uso sem o reconhecimento formal de conformidade, com fragilidade jurídica e contratual em caso de falha posterior. A permanência da condição mantém a etapa sem fechamento formal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar se todas as pendências técnicas, ensaios e documentos que condicionam o aceite estão concluídos e aprovados, listando eventuais restrições remanescentes; (ii) elaborar o termo de aceitação com o escopo aceito, ressalvas e anexos de evidência, colhendo as assinaturas das partes responsáveis; (iii) arquivar o termo assinado junto ao dossiê de qualidade, com registro fotográfico/documental do ato ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'TC-06' and item_numero = 5;

